const input = $input.first().json;
const body = input.body ?? input;

const DEFAULT_FUNCTIONS_URL = 'https://kbpkdnptzvsvoujirfwe.supabase.co/functions/v1';
const functionsUrl = ($env.SUPABASE_FUNCTIONS_URL || DEFAULT_FUNCTIONS_URL).replace(/\/$/, '');
const agentToken = $env.AGENT_TOKEN || $env.SUPABASE_AGENT_TOKEN || 'SUBSTITUA_PELO_TOKEN_HASH';
const publicSiteUrl = ($env.PUBLIC_SITE_URL || '').replace(/\/$/, '');

function first(...values) {
  return values.find((value) => value !== undefined && value !== null && String(value).trim() !== '');
}

function digits(value) {
  return String(value || '').replace(/\D/g, '');
}

function normalizePhone(value) {
  let cleaned = digits(value);
  if (!cleaned) return '';
  if (cleaned.startsWith('0')) cleaned = cleaned.slice(1);
  if (!cleaned.startsWith('55')) cleaned = `55${cleaned}`;
  return cleaned;
}

function getIncomingMessage(payload) {
  return String(first(
    payload.content,
    payload.message?.content,
    payload.message?.text,
    payload.data?.message?.conversation,
    payload.data?.message?.extendedTextMessage?.text,
    payload.data?.message?.imageMessage?.caption,
    payload.data?.message?.videoMessage?.caption,
    payload.data?.body,
    payload.text,
    payload.body,
    payload.message
  ) || '').trim();
}

function getIncomingPhone(payload) {
  const raw = first(
    payload.sender?.phone_number,
    payload.contact?.phone_number,
    payload.conversation?.contact_inbox?.source_id,
    payload.data?.key?.remoteJid,
    payload.data?.sender,
    payload.key?.remoteJid,
    payload.sender,
    payload.from,
    payload.phone,
    payload.remoteJid
  );
  return normalizePhone(raw);
}

function getIncomingName(payload) {
  return String(first(
    payload.sender?.name,
    payload.contact?.name,
    payload.data?.pushName,
    payload.pushName,
    payload.name,
    payload.customer_name
  ) || 'Cliente WhatsApp').trim();
}

function extractUuid(text) {
  return (String(text || '').match(/[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}/i) || [])[0] || '';
}

function extractCity(text, payload) {
  const explicit = first(payload.city, payload.data?.city, payload.context?.city);
  if (explicit) return String(explicit).trim();
  const match = String(text || '').match(/(?:em|de|para)\s+([a-zA-ZÀ-ÿ\s]{3,40})$/i);
  return match ? match[1].trim() : '';
}

function classifyIntent(message, payload) {
  const lower = message.toLowerCase();
  const productId = first(payload.product_id, payload.data?.product_id, payload.context?.product_id, extractUuid(message)) || '';

  if (/\b(rastre|rastreio|pedido|entrega|status|acompanhar|chegou|chega|encomenda)\b/i.test(lower)) {
    return { intent: 'order_tracking', productId };
  }

  if (/\b(humano|atendente|vendedor|consultor|pessoa|falar com alguem|me liga|ligar|whatsapp)\b/i.test(lower)) {
    return { intent: 'human_handoff', productId };
  }

  if (/\b(montador|montagem|instalador|instalação|instalacao|montar)\b/i.test(lower)) {
    return { intent: 'assemblers', productId };
  }

  if (productId || /\b(preço|preco|valor|quanto|detalhe|medida|dimensão|dimensao|estoque|disponível|disponivel|parcel)\b/i.test(lower)) {
    return { intent: productId ? 'product_detail' : 'product_search', productId };
  }

  if (/\b(interesse|interessado|quero|gostei|comprar|compraria|orçamento|orcamento|proposta|reservar|fechar)\b/i.test(lower)) {
    return { intent: 'lead_interest', productId };
  }

  if (/\b(sofá|sofa|guarda|roupa|mesa|cadeira|cama|rack|painel|cozinha|modulado|armário|armario|produto|móvel|movel|catálogo|catalogo|tem)\b/i.test(lower)) {
    return { intent: 'product_search', productId };
  }

  return { intent: 'fallback', productId };
}

async function callAgent(path, { method = 'GET', query = {}, body: requestBody } = {}) {
  const queryString = Object.entries(query)
    .filter(([, value]) => value !== undefined && value !== null && String(value) !== '')
    .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
    .join('&');

  const url = `${functionsUrl}/${path}${queryString ? `?${queryString}` : ''}`;
  const options = {
    method,
    url,
    headers: {
      'Content-Type': 'application/json',
      'x-agent-token': agentToken,
    },
    json: true,
  };

  if (requestBody) options.body = requestBody;

  return await this.helpers.httpRequest(options);
}

function productUrl(product) {
  if (!product) return '';
  if (product.public_url?.startsWith('http')) return product.public_url;
  if (publicSiteUrl) return `${publicSiteUrl}/product/${product.id}`;
  return product.public_url || `/product/${product.id}`;
}

function summarizeProducts(products = []) {
  if (!products.length) return 'Não encontrei produtos com esse termo. Você pode me dizer o tipo de móvel ou ambiente que procura?';
  const lines = products.slice(0, 5).map((product, index) => {
    const url = productUrl(product);
    return `${index + 1}. ${product.name}${product.category_name ? ` (${product.category_name})` : ''}${url ? ` - ${url}` : ''}`;
  });
  return `Encontrei estas opções:\n${lines.join('\n')}\n\nSe quiser, me diga o número ou envie o link do produto para eu registrar seu interesse.`;
}

function summarizeAssemblers(assemblers = []) {
  if (!assemblers.length) return 'Não encontrei montadores ativos para essa cidade agora. Posso chamar um atendente para verificar uma indicação?';
  return `Encontrei estes montadores:\n${assemblers.slice(0, 5).map((item, index) => `${index + 1}. ${item.name}${item.city ? ` - ${item.city}` : ''}${item.phone ? ` - ${item.phone}` : ''}`).join('\n')}`;
}

function summarizeOrders(orders = []) {
  if (!orders.length) return 'Não encontrei pedidos recentes vinculados a esse telefone. Se quiser, posso chamar um atendente para verificar manualmente.';
  return `Encontrei pedido(s) recente(s):\n${orders.slice(0, 5).map((order, index) => `${index + 1}. ${order.product_name || order.order_id} - ${order.order_stage} - ID: ${order.order_id}`).join('\n')}\n\nPara consultar um pedido específico, envie o ID do pedido.`;
}

const message = getIncomingMessage(body);
const phone = getIncomingPhone(body);
const customerName = getIncomingName(body);
const city = extractCity(message, body);
const { intent, productId } = classifyIntent(message, body);

let reply = '';
let leadId = null;
let apiResult = null;
let nextAction = 'send_reply';

try {
  if (!message) {
    reply = 'Oi! Recebi sua mensagem, mas não consegui ler o conteúdo. Pode mandar novamente?';
  } else if (intent === 'product_search') {
    apiResult = await callAgent('agent_products_search', { query: { q: message, limit: 5 } });
    reply = apiResult.ok ? summarizeProducts(apiResult.products) : `Não consegui buscar produtos agora: ${apiResult.error || 'erro desconhecido'}`;
  } else if (intent === 'product_detail') {
    let detailId = productId;
    if (!detailId) {
      const search = await callAgent('agent_products_search', { query: { q: message, limit: 1 } });
      detailId = search.products?.[0]?.id || '';
    }

    if (!detailId) {
      reply = 'Me envie o link ou o ID do produto para eu consultar os detalhes.';
    } else {
      apiResult = await callAgent('agent_product_by_id', { query: { id: detailId } });
      const product = apiResult.product;
      if (apiResult.ok && product) {
        const price = product.private?.price ? `\nValor: R$ ${product.private.price}` : '';
        const stock = product.private?.stock_status ? `\nEstoque: ${product.private.stock_status}` : '';
        const terms = product.private?.payment_terms ? `\nCondições: ${product.private.payment_terms}` : '';
        reply = `${product.name}\n${product.description || ''}${price}${stock}${terms}\n\nLink: ${productUrl(product)}\n\nQuer que eu registre seu interesse e chame um atendente?`;
      } else {
        reply = `Não consegui encontrar esse produto: ${apiResult.error || 'produto não localizado'}`;
      }
    }
  } else if (intent === 'lead_interest') {
    apiResult = await callAgent('agent_create_lead_interest', {
      method: 'POST',
      body: {
        customer_name: customerName,
        customer_phone: phone,
        message,
        source: 'n8n',
        context: {
          intent: 'catalog_interest',
          product_id: productId || undefined,
        },
      },
    });
    leadId = apiResult.lead_id || apiResult.lead?.id || null;
    reply = apiResult.ok
      ? 'Perfeito, registrei seu interesse. Um atendente pode continuar daqui e te passar os próximos detalhes.'
      : `Não consegui registrar seu interesse agora: ${apiResult.error || 'erro desconhecido'}`;
  } else if (intent === 'human_handoff') {
    const interest = await callAgent('agent_create_lead_interest', {
      method: 'POST',
      body: {
        customer_name: customerName,
        customer_phone: phone,
        message: `Cliente pediu atendimento humano. Mensagem original: ${message}`,
        source: 'n8n',
        context: { intent: 'human_handoff', product_id: productId || undefined },
      },
    });
    leadId = interest.lead_id || interest.lead?.id || null;
    if (leadId) {
      await callAgent('agent_update_lead_status', { method: 'POST', body: { lead_id: leadId, status: 'talking_human' } });
    }
    nextAction = 'handoff_human';
    reply = 'Claro. Vou encaminhar você para um atendente humano continuar o atendimento.';
  } else if (intent === 'order_tracking') {
    const explicitOrderId = extractUuid(message);
    if (explicitOrderId) {
      apiResult = await callAgent('agent_get_order_status', { query: { order_id: explicitOrderId } });
      reply = apiResult.ok
        ? `Seu pedido está em: ${apiResult.order.label}. Última atualização: ${apiResult.order.updated_at}.`
        : `Não consegui localizar esse pedido: ${apiResult.error || 'pedido não encontrado'}`;
    } else if (!phone) {
      reply = 'Para rastrear, me envie o telefone usado no pedido.';
    } else {
      apiResult = await callAgent('agent_find_recent_orders_by_phone', { query: { phone } });
      reply = apiResult.ok ? summarizeOrders(apiResult.orders) : `Não consegui buscar seus pedidos agora: ${apiResult.error || 'erro desconhecido'}`;
    }
  } else if (intent === 'assemblers') {
    apiResult = await callAgent('agent_get_assemblers', { query: { city, limit: 10 } });
    reply = apiResult.ok ? summarizeAssemblers(apiResult.assemblers) : `Não consegui buscar montadores agora: ${apiResult.error || 'erro desconhecido'}`;
  } else {
    if (phone) {
      apiResult = await callAgent('agent_create_lead_interest', {
        method: 'POST',
        body: {
          customer_name: customerName,
          customer_phone: phone,
          message: `Mensagem recebida sem intenção clara: ${message}`,
          source: 'n8n',
          context: { intent: 'fallback' },
        },
      });
      leadId = apiResult.lead_id || apiResult.lead?.id || null;
    }
    reply = 'Posso te ajudar com catálogo, preço de produto, rastreio de pedido, montadores ou atendimento humano. O que você gostaria de fazer?';
  }
} catch (error) {
  reply = 'Tive uma falha ao consultar o sistema agora. Vou encaminhar para atendimento humano.';
  nextAction = 'handoff_human';
  apiResult = { ok: false, error: error.message || String(error) };
}

return [
  {
    json: {
      ok: true,
      reply,
      next_action: nextAction,
      intent,
      lead_id: leadId,
      customer: {
        name: customerName,
        phone,
      },
      source: {
        provider: body.event ? 'chatwoot' : 'evolution_or_generic',
        raw_message: message,
      },
      debug: {
        product_id: productId || null,
        city: city || null,
        api_result: apiResult,
      },
    },
  },
];
